items = items.filter(i => i.json.pregunta);
items = items.filter((item, index, arr) =>
  index === arr.findIndex(t => t.json.id_detalle === item.json.id_detalle)
);
items.sort((a, b) => (a.json.id_detalle > b.json.id_detalle ? 1 : -1));

// 2. OBTENER RESUMEN
const allInputs = $input.all();
const resumenItem = allInputs.find(i => i.json.nota_final);

let nombre_estudiante = "Estudiante";
try {
  const nodoNombre = $('Normalizador_respuestas').first();
  if (nodoNombre && nodoNombre.json.nombre_completo) {
    nombre_estudiante = nodoNombre.json.nombre_completo;
  }
} catch (e) {}

// Resumen
const resumen = resumenItem ? resumenItem.json : {};
resumen.nombre_estudiante = nombre_estudiante;


// 3. NORMALIZACIÓN
function normalize(str) {
  return (str || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/^correcta:\s*/i, "")
    .replace(/^✔\s*/i, "")
    .replace(/\s+/g, " ");
}

for (const item of items) {
  const data = item.json;
  data.originalUsuario = data.respuesta_usuario || "";
  data.originalCorrecta = data.respuesta_correcta || "";
  data.usuarioLimpio = normalize(data.respuesta_usuario);
  data.correctaLimpia = normalize(data.respuesta_correcta);
  data.esCorrectaReal = data.usuarioLimpio === data.correctaLimpia;
}

// 4. CÁLCULOS
const total = items.length;
const correctas = items.filter(item => item.json.esCorrectaReal).length;
const porcentaje = total > 0 ? ((correctas / total) * 100).toFixed(0) : 0;

// 5. GENERAR HTML FINAL
