    if (data.explicacion) {
      htmlPdf += `
        <div class="explicacion-box">
          <strong>Explicación:</strong> ${data.explicacion}
        </div>`;
    }
  }

  htmlPdf += `</div>`;
}

htmlPdf += `</body></html>`;

// 7. RETORNAR
return [{
  json: {
    emailTo: resumen.correo,
    emailSubject: `Resultados Evaluación: ${resumen.nota_final}`,
    emailBody: `
      Hola,<br><br>
      Tu evaluación ha sido revisada.<br><br>
      <strong>Nota Final:</strong> ${resumen.nota_final}<br>
      <strong>Acierto:</strong> ${porcentaje}% (${correctas}/${total})<br><br>
      Se adjunta el PDF con el desglose completo.<br><br>
      Saludos.
    `,
    pdfHtml: htmlPdf,
    pdfFileName: `Feedback_${resumen.id_evaluacion}.pdf`
  }
}];

const respuestas = $items('Normalizador_respuestas').map(i => i.json);

let banco = [];
try {
  banco = $items('Banco preguntas').map(i => i.json);
} catch (e) {
  banco = [];
}

// Helper de normalización
function norm(str) {
  return String(str || '').trim().toLowerCase();
}

// Crear índice del banco
const indexBanco = new Map();

for (const q of banco) {
  const idEval = String(q.id_evaluacion || '').trim();
  const preguntaNorm = norm(q.pregunta);
  const key = `${idEval}|||${preguntaNorm}`;
  indexBanco.set(key, q);

  if (!idEval) {
    const keySinEval = `|||${preguntaNorm}`;
    if (!indexBanco.has(keySinEval)) indexBanco.set(keySinEval, q);
  }
}

const salida = [];

for (const r of respuestas) {

  const correo = r.correo || "SIN_CORREO_DETECTADO"; 

  const id_evaluacion = r.id_evaluacion;
  const id_intento = r.id_intento;
  const nombre_completo = r.nombre_completo;

  const preguntaOriginal = String(r.pregunta || "").trim();
  const preguntaNorm = norm(preguntaOriginal);
  const respuestaUsuario = String(r.respuesta_usuario ?? r.respuesta ?? "").trim();

  const keyConEval = `${String(id_evaluacion || '').trim()}|||${preguntaNorm}`;
  let registroBanco = indexBanco.get(keyConEval);

  if (!registroBanco) {
    const keySinEval = `|||${preguntaNorm}`;
    registroBanco = indexBanco.get(keySinEval);
  }

  let respuestaCorrectaTexto = "No encontrada";
  let estado = "Incorrecta";
  let explicacion = "";

  if (registroBanco) {
    const letra = String(registroBanco.respuesta_correcta || "").trim().toUpperCase();
    const campo = "alt_" + letra;

    const valorAlt = registroBanco[campo];
    const valorAltStr = valorAlt == null ? "" : String(valorAlt);

    respuestaCorrectaTexto = valorAltStr.trim() || "No encontrada";
    explicacion = registroBanco.explicacion ? String(registroBanco.explicacion) : "";

    if (
      respuestaUsuario !== "" &&
      respuestaCorrectaTexto !== "No encontrada" &&
      respuestaUsuario.toLowerCase() === respuestaCorrectaTexto.toLowerCase()
    ) {
      estado = "Correcta";
    }
  }

  salida.push({
    json: {
      id_evaluacion,
      id_intento,
      nombre_completo,
      correo, 
      pregunta: preguntaOriginal,
      respuesta_usuario: respuestaUsuario,
      respuesta_correcta: respuestaCorrectaTexto,
      estado,
      explicacion,

    },
  });
}

return salida;

// =======================================
// 1. Obtener todas las filas del desglose
// =======================================
const desglose = $input.all().map(item => item.json);

// Agrupación por evaluación + intento + correo
const porIntento = {};

function normEstado(str) {
  return String(str || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

for (const fila of desglose) {
  const id_evaluacion = String(fila.id_evaluacion || '').trim();
  const id_intento = String(fila.id_intento || fila.hash_intento || '').trim();
  const correo = String(fila.correo || '').trim();
  const nombre_completo = fila.nombre_completo || '';

  const key = `${id_evaluacion}||${id_intento}||${correo}`;

  if (!porIntento[key]) {
    porIntento[key] = {
      id_evaluacion,
      id_intento,
      correo,
      nombre_completo,
      total_preguntas: 0,
      respuestas_correctas: 0,
    };
  }

  porIntento[key].total_preguntas += 1;

  const estado = normEstado(fila.estado);
  if (estado === "correcta" || estado === "correcto") {
    porIntento[key].respuestas_correctas += 1;
  }
}

// ===============================
// 2. Construcción del resumen final
// ===============================
const salida = [];

for (const key in porIntento) {
  const data = porIntento[key];

  const porcentaje =
    data.total_preguntas > 0
      ? data.respuestas_correctas / data.total_preguntas // ← AHORA DECIMAL
      : 0;

  const nota_final = (1 + porcentaje * 6).toFixed(2);

  salida.push({
    json: {
      id_evaluacion: data.id_evaluacion,
      id_intento: data.id_intento,
      correo: data.correo,
      nombre_completo: data.nombre_completo,
      total_preguntas: data.total_preguntas,
      respuestas_correctas: data.respuestas_correctas,
      porcentaje_aciertos: porcentaje, // ← decimal 0–1
      nota_final,
    },
  });
}

return salida;

const root = items[0].json;


let entrada = root.body || root;

if (typeof entrada === 'string') {
  try {
    entrada = JSON.parse(entrada);
  } catch (e) {
    return [];
  }
}

const id_evaluacion = entrada.id_evaluacion;

const id_intento =
  entrada.id_intento ||   
  entrada.data ||         
  entrada.hash_intento || 
  "";

// Correo (puede venir como "correo" o "email")
const correo = entrada.correo || entrada.email || "";

const respuestas = entrada.respuestas || {};

let nombre_completo =
  entrada.nombre_completo ||
  entrada["Nombre Completo"] ||
  entrada.nombre ||
  "";

// Si sigue vacío y existe en respuestas → lo tomamos
if (!nombre_completo && respuestas["Nombre Completo"]) {
  const arr = respuestas["Nombre Completo"];
  if (Array.isArray(arr) && arr.length > 0) {
    nombre_completo = String(arr[0]).trim();
  }
}

// Campos que NO son preguntas
const camposIgnorar = new Set([
  "Nombre Completo",
  "Marca temporal",
  "Dirección de correo electrónico",
  "Puntuación",
]);

const salida = [];

for (const tituloPregunta of Object.keys(respuestas)) {
  if (camposIgnorar.has(tituloPregunta)) continue;

  const respuestaArray = respuestas[tituloPregunta] || [];
  const respuestaUsuario =
    respuestaArray.length > 0 ? String(respuestaArray[0]).trim() : "";

  salida.push({
    json: {
      id_evaluacion,
      id_intento,
      correo,
      nombre_completo,
      pregunta: tituloPregunta,
      respuesta_usuario: respuestaUsuario,
    },
  });
}

return salida;

const respuestas = $input.all().map(i => i.json);
const salida = [];

for (let idx = 0; idx < respuestas.length; idx++) {
  const r = respuestas[idx];

  const id_evaluacion = r.id_evaluacion;
  const id_intento = r.id_intento;
  const correo = r.correo;

  // ID único por detalle (pregunta dentro del intento)
  const id_detalle = `${id_intento}_${idx + 1}`;

  salida.push({
    json: {
      id_evaluacion,
      id_intento,
      id_detalle,
      correo,
      pregunta: r.pregunta,
      respuesta_usuario: r.respuesta_usuario,
      respuesta_correcta: r.respuesta_correcta,
      estado: r.estado,
      explicacion: r.explicacion,
    },
  });
}

return salida;
return salida;

const items = $input.all();


const salida = [];

for (const item of items) {
  const data = item.json;

  // Verificamos si la respuesta es correcta
  const esCorrecta = data.respuesta_usuario === data.respuesta_correcta;

  if (esCorrecta) {
    // Eliminamos la explicación si es correcta
    delete data.explicacion;
  }

  // Agregamos el item modificado a la salida
  salida.push({ json: data });
}

return salida;

// 1) OBTENER EL PAYLOAD REAL DESDE raw_payload

let raw = $json.raw_payload;
let payload;

// Si viene como objeto, usarlo directamente
if (typeof raw === "object") {
  payload = raw;
}

// Si viene como string, limpiarlo y parsearlo
if (typeof raw === "string") {
  try {
    let cleaned = raw
      .replace(/\\"/g, '"')   
      .replace(/"{/g, '{')    
      .replace(/}"/g, '}');   
    payload = JSON.parse(cleaned);
  } catch (e) {
    return {
      ok: false,
      error: "RAW_PAYLOAD inválido",
      detalle: raw
    };
  }
}

// 2) VALIDAR CAMPOS OBLIGATORIOS REALES DEL FLUJO
const required = ["id_evaluacion", "id_intento", "correo", "respuestas"];
const faltantes = required.filter(k => !payload[k]);

if (faltantes.length > 0) {
  return {
    ok: false,
    error: "JSON con campos faltantes",
    faltantes,
    detalle: payload
  };
}


// 3) SI TODO ESTÁ OK → devolver JSON limpio
return {
  ok: true,
  payload
};

const view = $json.webViewLink;

// Extraer ID del archivo
const match = view.match(/\/d\/(.*?)\//);
const fileId = match ? match[1] : null;

return {
  link_pdf: view,
  link_descarga: `https://drive.google.com/uc?export=download&id=${fileId}`,
  fileId
};

// ================================
// 1. Tomar datos desde Generar_link
// ================================
const fileData = $items("Generar_link")[0].json;

// Asegurar que el fileId exista
if (!fileData.fileId) {
  throw new Error("No se encontró fileId desde Generar_link");
}

// ================================
// 2. Tomar datos desde config_eval
// ================================
const configRows = $items("config_eval");

// Buscar doc asociado al id_evaluacion que viene desde Generar_link
const idEval = fileData.id_evaluacion;

const fila = configRows.find(r => r.json.id_evaluacion === idEval);

if (!fila) {
  throw new Error(`No se encontró la evaluación ${idEval} en Configuracion_evaluaciones`);
}

const correoDocente = fila.json.correo_docente;

// ================================
// 3. Devolver combinación final
// ================================
return [
  {
    json: {
      fileId: fileData.fileId,
      docente_correo: correoDocente
    }
  }
];

// SIEMPRE obtener el webhook (último item que entra)
const items = $input.all();
const entrada = items[items.length - 1].json;

// Extraer correo correctamente
const email = String(
  entrada.email ||
  entrada.correo ||
  entrada.body?.email ||
  entrada.body?.correo ||
  ""
).trim().toLowerCase();

// Token opcional
const token = String(
  entrada.token ||
  entrada.body?.token ||
  ""
).trim();

// Registros del Google Sheet
const registros = $items("Leer_Autorizados").map(i => i.json);

let autorizado = false;
let motivo = "";
let estudiante = null;

// Validación
for (const row of registros) {
  const rowEmail = String(row.email || "").trim().toLowerCase();
  const rowToken = String(row.token || "").trim();
  const activo = String(row.activo || "").trim().toLowerCase() === "si";

  if (!activo) continue;

  if (email === rowEmail || token === rowToken) {
    autorizado = true;
    estudiante = row;
    break;
  }
}

if (!autorizado) motivo = "Credenciales inválidas";

return [{
  json: {
    autorizado,
    motivo,
    estudiante,
    email_entrada: email,
    ...entrada
  }
}];

// Entrada: viene desde 2 nodos de Google Sheets
const resumenItems = $items('Leer_Resumen_Preguntas') || [];
const desgloseItems = $items('Leer_Desgloce_Preguntas') || [];

// Normalizar arrays de JSON
const resumen = resumenItems.map(i => i.json);
const desglose = desgloseItems.map(i => i.json);

// ---------- Helpers ----------
function parsePercent(v){
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number'){
    if (v > 1 && v <= 100) return v/100;
    return v;
  }
  let s = String(v).trim();
  if (s.endsWith('%')) s = s.slice(0,-1).trim();
  const n = Number(s.replace(',', '.'));
  if (isNaN(n)) return null;
  if (n > 1 && n <= 100) return n/100;
  return n;
}

function median(arr){
  if (!arr.length) return null;
  const a = arr.slice().sort((x,y)=>x-y);
  const mid = Math.floor(a.length/2);
  return a.length%2 ? a[mid] : (a[mid-1]+a[mid])/2;
}

// ---------- Cálculo principal ----------
const estudiantes = resumen.map(r => ({
  correo: r.correo || r.email || r.Correo || r.CORREO || r.email_estudiante || '',
  id_intento: r.id_intento || r.id_intento || r.hash_intento || '',
  nombre: r.nombre_completo || r.nombre || r.Nombre || '',
  porcentaje_raw: parsePercent(r.porcentaje_aciertos)
}));

const porcentajes = estudiantes.map(s => s.porcentaje_raw).filter(v => v !== null && v !== undefined);
const totalEst = estudiantes.length;
const validos = porcentajes.length;
const promedio = validos ? (porcentajes.reduce((a,b)=>a+b,0)/validos) : null;
const mediana = validos ? median(porcentajes) : null;

const distr = { '0-39':0,'40-59':0,'60-79':0,'80-100':0 };
for (const p of porcentajes){
  const pct = p*100;
  if (pct < 40) distr['0-39']++;
  else if (pct < 60) distr['40-59']++;
  else if (pct < 80) distr['60-79']++;
  else distr['80-100']++;
}

const incompletos = estudiantes.filter(s => s.porcentaje_raw === null).length;

const fallosPorPregunta = {};
for (const row of desglose){
  const preg = row.pregunta || row.Pregunta || 'SIN_PREGUNTA';
  const estado = (row.estado || '').toString().trim().toLowerCase();
  if (estado && (estado === 'incorrecta' || estado === 'incorrecto' || estado === 'false' || estado === 'no')){
    fallosPorPregunta[preg] = (fallosPorPregunta[preg] || 0) + 1;
  }
}
const preguntasOrdenadas = Object.entries(fallosPorPregunta).sort((a,b)=>b[1]-a[1]).map(([preg, fallos])=>({pregunta:preg, fallos}));

const topEst = estudiantes.filter(s=>s.porcentaje_raw!==null).sort((a,b)=>b.porcentaje_raw - a.porcentaje_raw).slice(0,10).map(s=>({correo:s.correo,nombre:s.nombre,porcentaje:(s.porcentaje_raw*100).toFixed(2)}));

return [{
  json: {
    total_registros: resumen.length,
    total_estudiantes: totalEst,
    registros_incompletos: incompletos,
    promedio_acierto: promedio===null? null : Number((promedio*100).toFixed(2)),
    mediana_acierto: mediana===null? null : Number((mediana*100).toFixed(2)),
    distribucion_segmentos: distr,
    preguntas_mas_falladas: preguntasOrdenadas.slice(0,10),
    top_estudiantes: topEst,
    raw_estudiantes: estudiantes
  }
}];

// Genera un HTML con Chart.js embebido usando los datos del nodo anterior
const data = $input.first().json;

const promedio = data.promedio_acierto ?? 0;
const mediana = data.mediana_acierto ?? 0;
const distr = data.distribucion_segmentos || { '0-39':0,'40-59':0,'60-79':0,'80-100':0 };
const topPreg = data.preguntas_mas_falladas || [];
const topEst = data.top_estudiantes || [];

const html = `
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Dashboard Evaluación</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <style>body{font-family:Arial,Helvetica,sans-serif;padding:20px;color:#333} .card{border:1px solid #e6e6e6;border-radius:8px;padding:12px;margin-bottom:12px}</style>
</head>
<body>
  <h2>Dashboard — Estadísticas Agregadas</h2>
  <div class="card">
    <strong>Promedio de acierto:</strong> ${promedio}% &nbsp; | &nbsp; <strong>Mediana:</strong> ${mediana}%
  </div>

  <div class="card">
    <canvas id="barPreg" height="120"></canvas>
  </div>

  <div class="card">
    <canvas id="pieDistrib" height="120"></canvas>
  </div>

  <div class="card">
    <h4>Top preguntas más falladas</h4>
    <ol>
